@media screen and (max-width: 961px) {

    header {

        nav {

            .navigation {

                .nav-item {
                    margin-right: 30px;
                }
            }
        }
    }

    main {
        grid-template-columns: 1fr;
        justify-content: center;

        .content {
            margin: 0 auto;
        }
    }

    .sidebar {
        display: none;
    }
}

@media screen and (max-width: 769px) {

    header {

        nav {
            padding-top: 20px;
            position: static;

            .logo {
                font-size: 38px;
            }

            .navigation {
                position: absolute;
                height: 100vh;
                width: 50vw;
                left: 0;
                top: 0;
                flex-direction: column;
                justify-content: center;
                align-items: center;
                background-color: $darkgrey;
                z-index: 99999;
                transform: translateX(-100%);
                transition: all 0.3s;

                .nav-item {
                    margin: 0 0 20px 0;
                    color: $white;

                    .nav-item-desc {
                        display: none;
                    }

                    .nav-item-head {
                        font-size: 20px;
                    }

                    &:last-child {
                        margin: 0;
                    }
                }

                .current {

                    .arrow {
                        display: none;
                    }

                    .nav-item-head {
                        font-size: 20px;
                        color: $grey;
                    }
                }
            }

            .show {
                transform: translateX(0%);
                position: fixed;
            }

            .hamburger {
                display: block;
            }

            .opened {
                
                .line2 {
                    height: 0;
                    margin: 0;
                }

                .line1 {
                    transform: rotate(45deg);
                    position: absolute;
                }
                .line3 {
                    transform: rotate(-45deg);
                    position: absolute;
                }
            }

            .active {
                transform: translateX(0%);
            }
        }
    }

    main {

        .content {
            padding-right: 0;

            .about {
                padding-top: 50px;
            }

            .projects {
                padding-bottom: 50px;

                .projects-types {
                    justify-content: center;
                }

                .work {
                    flex-direction: column;

                    .column {
                        margin: 0 auto;
                    }
                }
            }
        }
    }

    footer {

        .footer {
            flex-direction: column;
            padding: 35px 10px;
            text-align: center;

            p {
                margin: 0 auto 10px auto;
                line-height: normal;

                &:last-child {
                    margin: 0 auto;
                }
            }
        }
    }
}

@media screen and (max-width: 481px) {

    footer {

        .footer {
            p,span,a {
                font-size: 14px;
            }
        }
    }
}
